}

interface Mover {
  key: string;
  glyphFrom: string;
  glyphTo: string;
  x0: number;
  x1: number;
  start: number;
  end: number;
  /** When an arriving letter starts to fade in. */
  fadeAt: number;
  enterAt: number;
  enterEnd: number;
  accentAt: number;
  accentEnd: number;
  dir: number;
  lift: number;
  fadeOut: boolean;
  fadeIn: boolean;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function AnagramShuffle(props: AnagramShuffleProps) {
  const {
    from = DEFAULT_SOURCE,
    to = DEFAULT_TARGET,
    accent = "#3B5BFD",
    ink,
    background,
    grain = true,
    scale: zoom = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    anagramShuffleTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const c = THEMES[theme];
  const fg = ink ?? c.fg;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const a = useMemo(() => Array.from(from), [from]);
  const b = useMemo(() => Array.from(to), [to]);
  const la = useMemo(() => layoutWord(a), [a]);
  const lb = useMemo(() => layoutWord(b), [b]);
  const span = Math.max(la.total, lb.total, 0.1);
  const F = Math.min(H * 0.52, (W * 0.7) / span);
  // Optically centre lowercase: weight the x-height over the cap height.
  const baseline = H / 2 + ((CAP * 0.35 + XH * 0.65) * F) / 2;

  const movers = useMemo<Mover[]>(() => {
    const { src, orphans } = mapLetters(a, b);
    const list: Mover[] = [];
    b.forEach((ch, j) => {
      const i = src[j];
      const x1 = (lb.xs[j] + lb.ws[j] / 2) * F;
      const acc = tl.get(`accent:${j}`);
      if (i < 0) {
        const arrive = tl.get(`arrive:${j}`);
        list.push({
          key: `in-${j}`,
          glyphFrom: ch,
          glyphTo: ch,
          x0: x1,
          x1,
          start: arrive.start,
          end: arrive.end,
          fadeAt: arrive.start + arrive.beat("fade"),
          enterAt: 0,
          enterEnd: 16,
          accentAt: acc.start,
          accentEnd: acc.end,
          dir: 1,
          lift: 0,
          fadeOut: false,
          fadeIn: true,
        });
        return;
      }
      const x0 = (la.xs[i] + la.ws[i] / 2) * F;
      const dx = x1 - x0;
      const still = Math.abs(dx) < F * 0.2;
      const move = tl.get(`letter:${i}`);
      const enter = tl.get(`enter:${i}`);
      list.push({
        key: `m-${i}`,
        glyphFrom: a[i],
        glyphTo: ch,
        x0,
        x1,
        start: move.start,
        end: move.end,
        fadeAt: move.end,
        enterAt: enter.start,
        enterEnd: enter.end,
        accentAt: acc.start,
        accentEnd: acc.end,
        dir: still ? 1 : dx > 0 ? 1 : -1,
        lift: still
          ? F * 0.1
          : Math.min(F * 0.48, Math.max(F * 0.18, Math.abs(dx) * 0.42)),
        fadeOut: false,
        fadeIn: false,
      });
    });
    for (const i of orphans) {
      const x0 = (la.xs[i] + la.ws[i] / 2) * F;
      const move = tl.get(`letter:${i}`);
      const enter = tl.get(`enter:${i}`);
      list.push({
        key: `o-${i}`,
        glyphFrom: a[i],
        glyphTo: a[i],
        x0,
        x1: x0,
        start: move.start,
        end: move.end,
        fadeAt: move.end,
        enterAt: enter.start,
        enterEnd: enter.end,
        accentAt: Number.POSITIVE_INFINITY,
        accentEnd: Number.POSITIVE_INFINITY,
        dir: -1,
        lift: F * 0.3,
        fadeOut: true,
        fadeIn: false,
      });
    }
    return list;
  }, [a, b, la, lb, F, tl]);

  const ordered = useMemo(
    () => [...movers].sort((m, n) => m.dir - n.dir),
    [movers],
  );

  const halo = Math.max(2, F * 0.03);
  const haloShadow = [0, 45, 90, 135, 180, 225, 270, 315]
    .map((deg) => {
      const r = (deg * Math.PI) / 180;
      return `${(Math.cos(r) * halo).toFixed(2)}px ${(Math.sin(r) * halo).toFixed(2)}px 0 ${stage}`;
    })
    .join(", ");

  // One stage-space gradient: every glyph samples it where it stands, so a
  // letter picks up colour as it travels across the word.
  const angle = 100 + 5 * Math.sin(t * 0.018);
  const rad = (angle * Math.PI) / 180;
  const lineLen = W * Math.abs(Math.sin(rad)) + H * Math.abs(Math.cos(rad));
  const along = (x: number) => lineLen / 2 + (x - W / 2) * Math.sin(rad);
  const s0 = along(W / 2 - (span * F) / 2 - F * 0.1);
  const s1 = along(W / 2 + (span * F) / 2 + F * 0.1);
  // The cool end of the palette is the accent itself.
  const stops = [accent, ...c.stops.slice(1)];
  const gradient = `linear-gradient(${angle.toFixed(2)}deg, ${stops
    .map(
      (col, i) =>
        `${col} ${(s0 + ((s1 - s0) * i) / (stops.length - 1)).toFixed(1)}px`,
    )
    .join(", ")})`;
  const PAD = 0.12;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={zoom}>
        <div
          style={{
            position: "absolute",
            left: W / 2,
            top: baseline,
            fontFamily: serif,
            fontWeight: 400,
            fontSize: F,
            lineHeight: LINE,
            fontKerning: "none",
            whiteSpace: "pre",
          }}
        >
          {ordered.map((m) => {
            const over = m.dir > 0;
            const pose = (f: number) => {
              const p = interpolate(f, [m.start, m.end], [0, 1], {
                ...CLAMP,
                easing: EASE_IO,
              });
              const arc = Math.sin(Math.PI * p);
              const enter = interpolate(f, [m.enterAt, m.enterEnd], [0, 1], {
                ...CLAMP,
                easing: EASE_OUT,
              });
              const y =
                (over ? -m.lift : m.lift * 0.7) * arc + (1 - enter) * F * 0.14;
              const acc = interpolate(f, [m.accentAt, m.accentEnd], [0, 1], {
                ...CLAMP,
                easing: EASE_OUT,
              });
              const bump = Math.sin(Math.PI * acc) * F * 0.045;
              return {
                p,
                arc,
                enter,
                acc,
                yOff: y - bump,
                scale: over ? 1 + 0.09 * arc : 1 - 0.07 * arc,
              };
            };
            const { p, arc, enter, acc, yOff, scale } = pose(t);
            const x = m.x0 + (m.x1 - m.x0) * p;
            const step = Math.max(speed, 1e-3);
            // A glyph is about F tall above its baseline origin, so a scale
            // step moves its top by roughly that much times the step.
            const moving = [pose(t - step), pose(t + step)].some(
              (q) =>
                Math.abs(q.yOff - yOff) > 1e-3 ||
                Math.abs(q.scale - scale) * F > 1e-3,
            );
            const solid = over
              ? fg
              : interpolateColors(arc, [0, 1], [fg, c.dim]);
            // Gradient share: a flash while a letter flies over, then for good.
            const fill = Math.max(over ? arc * 0.85 : 0, acc);
            let opacity = enter;
            if (m.fadeOut) opacity *= interpolate(p, [0, 0.6], [1, 0], CLAMP);
            if (m.fadeIn)
              opacity = interpolate(t, [m.fadeAt, m.end], [0, 1], {
                ...CLAMP,
                easing: EASE_OUT,
              });
            const swap = m.glyphFrom !== m.glyphTo;
            const mix = swap ? interpolate(p, [0.35, 0.65], [0, 1], CLAMP) : 1;
            const glyph = (o: number, ch: string, key: string) => {
              if (o <= 0) return null;
              const left = -advance(ch) * F * 0.5;
              // Stage position of the gradient span's local origin.
              const gx = W / 2 + x + scale * (left - PAD * F);
              const gy = baseline + yOff - scale * ASC * F;
              return (
                <div key={key} style={{ opacity: o }}>
                  {over && arc > 0.02 ? (
                    <span
                      style={{
                        position: "absolute",
                        left,
                        top: 0,
                        color: stage,
                        textShadow: haloShadow,
                      }}
                    >
                      {ch}
                    </span>
                  ) : null}
                  {fill < 1 ? (
                    <span
                      style={{
                        position: "absolute",
                        left,
                        top: 0,
                        color: solid,
                        opacity: 1 - fill,
                      }}
                    >
                      {ch}
                    </span>
                  ) : null}
                  {fill > 0 ? (
                    <span
                      style={{
                        position: "absolute",
                        left: left - PAD * F,
                        top: 0,
                        padding: `0 ${PAD}em`,
                        opacity: fill,
                        color: "transparent",
                        backgroundImage: gradient,
                        backgroundSize: `${W / scale}px ${H / scale}px`,
                        backgroundPosition: `${-gx / scale}px ${-gy / scale}px`,
                        backgroundRepeat: "no-repeat",
                        WebkitBackgroundClip: "text",
                        backgroundClip: "text",
                      }}
                    >
                      {ch}
                    </span>
                  ) : null}
                </div>
              );
            };
            return (
              <div
                key={m.key}
                style={{
                  position: "absolute",
                  left: 0,
                  top: -ASC * F,
                  opacity,
                  transform: `translate(${x}px, ${yOff}px) scale(${scale})${glide(moving)}`,
                  transformOrigin: `0px ${ASC * F}px`,
                }}
              >
                {swap ? glyph(1 - mix, m.glyphFrom, "from") : null}
                {glyph(mix, m.glyphTo, "to")}
              </div>
            );
          })}
        </div>
      </ScaleLayer>
      {grain ? <Grain opacity={c.grain} /> : null}
    </AbsoluteFill>
  );
}
